/* From Uiverse.io by SelfMadeSystem - Tags: animation, card, glow, rainbow */
.__UIV_SCOPE__ .card {
  position: relative;
  width: 190px;
  color: white;
  height: 260px;
  background: #444;
  border-radius: 14px;
}

.__UIV_SCOPE__ .bg {
  position: absolute;
  z-index: -1;
  inset: -4px;
  border-radius: 16px;
  overflow: hidden;
}

.__UIV_SCOPE__ .uwu {
  filter: blur(8px);
  transition: filter 0.3s;
}

.__UIV_SCOPE__ .bg::before {
  content: '';
  position: absolute;
  aspect-ratio: 1/1;
  top: 50%;
  left: 50%;
  min-width: 150%;
  min-height: 150%;
  background-image: conic-gradient(
    hsl(0, 100%, 50%),
    hsl(30, 100%, 50%),
    hsl(60, 100%, 50%),
    hsl(90, 100%, 50%),
    hsl(120, 100%, 50%),
    hsl(150, 100%, 50%),
    hsl(180, 100%, 50%),
    hsl(210, 100%, 50%),
    hsl(240, 100%, 60%),
    hsl(270, 100%, 50%),
    hsl(300, 100%, 50%),
    hsl(330, 100%, 50%),
    hsl(360, 100%, 50%)
  );
  animation: speeen 4s linear infinite;
  transform-origin: 0% 0%;
  transform: rotate(0deg) translate(-50%, -50%);
}

@keyframes speeen {
  from {
    transform: rotate(0deg) translate(-50%, -50%);
  }

  to {
    transform: rotate(360deg) translate(-50%, -50%);
  }
}

.__UIV_SCOPE__ .content {
  position: relative;
  padding: 14px 16px;
}

.__UIV_SCOPE__ .img {
  height: 5em;
  width: 5em;
  margin: auto;
  background-color: #fff3;
  border-radius: 1em;
}

.__UIV_SCOPE__ .img svg {
  height: 100%;
  fill: white;
}

.__UIV_SCOPE__ .content div {
  text-align: center;
}

.__UIV_SCOPE__ .h1 {
  margin-top: 1em;
  margin-bottom: 0.5em;
  font-size: 1em;
  font-weight: 600;
}

.__UIV_SCOPE__ .p {
  font-size: 0.75em;
}

.__UIV_SCOPE__ .p p {
  margin-top: 0.5em;
  padding: 0.5em;
  background-color: #0003;
  border-radius: 1em;
}
